"""Build the reviewed raw services slice from explicit source-grounded assertions.

No network, inference-by-name or aggregate loss calculation occurs here.
Run from repository root; outputs services.json.
"""
import json, pathlib, re

ROOT=pathlib.Path(__file__).resolve().parents[4]
OUT=ROOT/'research/raw/deep-investigation/services.json'
ROUTE='/follow-the-money'
D={'asOf':'2026-10-06','sources':[],'entities':[],'relationships':[],'records':[],'localities':[]}

def source(id,title,url,publisher,date,locator,summary,tier='documented',limits=[]):
    D['sources'].append(dict(id=id,title=title,url=url,publisher=publisher,publishedAt=date,retrievedAt='2026-10-07',locator=locator,summary=summary,tier=tier,limitations=limits))

def geo(src,states=[],scope=None,basis=None,note=None,localities=[]):
    return [dict(scope=scope or ('state' if len(states)==1 else 'multi-state' if states else 'national'),stateCodes=states,localityIds=localities,basis=basis or ('programme-coverage' if states else 'national-context'),note=note or 'Only the stated programme or institution geography is established; no whole-state spend allocation is inferred.',sourceIds=src)]

def dims(src,domains,layers,g=None,limits=[]):
    return dict(sourceIds=src,domains=domains,layers=layers,geography=g or geo(src),route=ROUTE,limitations=limits)

def entity(id,label,type,summary,src,domains,g=None,canonical=None,identity=None):
    row=dict(id=id,label=label,type=type,resolved=True,identityBasis=identity or 'Named in the cited document in this specific institutional role; no surname, address or group-brand merge.',summary=summary,**dims(src,domains,['people' if type=='person' else 'legal' if type in ['court','case'] else 'organisations'],g))
    if canonical:row['canonicalId']=canonical
    D['entities'].append(row)

def amt(value,unit,stage,period,currency='INR'):
    return dict(value=value,currency=currency,unit=unit,stage=stage,period=period)

def rel(id,fr,to,kind,label,summary,src,domains,layers,record,amounts=[],tier='documented',status='Source-retained relationship within the stated source period; read evidence tier',asof=None,start=None,end=None,g=None,limits=[],alternatives=[],falsifier=None,response=True):
    D['relationships'].append(dict(id=id,**{'from':fr,'to':to},kind=kind,label=label,summary=summary,tier=tier,status=status,statusAsOf=asof,fromDate=start,toDate=end,dateBasis='Exact event/observation dates only; amounts retain separate periods. Null dates mean the source provides no exact day.',recordIds=[record],responseIds=[record] if response else [],amounts=amounts,alternativeExplanations=alternatives,falsifier=falsifier,**dims(src,domains,layers,g,limits)))

def record(id,title,summary,src,entities,relationships,domains,layers,period,response,alternatives,falsifier,amounts,tier,status,asof,start,end,g=None,limits=[]):
    D['records'].append(dict(id=id,title=title,summary=summary,kind='investigation-case',tier=tier,status=status,statusAsOf=asof,fromDate=start,toDate=end,dateBasis='Dates bound the explicitly described events or reviewed procedural observations; fiscal and transaction periods remain attached to each amount.',entityIds=entities,relationshipIds=relationships,period=period,response=response,alternativeExplanations=alternatives,falsifier=falsifier,amounts=amounts,**dims(src,domains,layers,g,limits)))

