def readable(value):
    if isinstance(value,dict):
        return {key:readable(item) for key,item in value.items()}
    if isinstance(value,list):
        return [readable(item) for item in value]
    if isinstance(value,str) and ' ' in value and not value.startswith('http'):
        value=re.sub(r'(?<=\d)(?=[A-Za-z])',' ',value)
        value=re.sub(r'(?<=[A-Za-z])(?=\d)',' ',value)
        value=re.sub(r'(?<=[A-Za-z])(?=§)',' ',value)
        value=value.replace('ScheduleB','Schedule B').replace('Committee’s9threport','Committee’s 9th report')
    return value

